import { useEffect, useRef } from 'react'
import { useOutletContext, useParams } from 'react-router'
import { useNote } from '../../hooks/useNote.js'
import { useUpdateNote } from '../../hooks/useUpdateNote.js'
import { useVaultTree } from '../../hooks/useVaultTree.js'
import { useCodeMirrorEditor } from '../../hooks/useCodeMirrorEditor.js'
import { canEdit } from '../../api/vaults.js'
import type { Vault } from '../../api/vaults.js'
import { PropertyPanel } from '../../components/vault/PropertyPanel.js'

const SAVE_DEBOUNCE_MS = 1200

export function NoteView() {
  const { vaultId } = useParams<{ vaultId: string }>()
  const path = useParams()['*']
  const vault = useOutletContext<Vault | undefined>()
  const note = useNote(vaultId!, path!)

  if (note.isPending) return null
  if (note.isError) return <div className="p-8 text-muted-foreground">Note not found.</div>

  // Conservative default: unknown access (vault undefined) => read-only.
  const readOnly = !canEdit(vault?.access)

  return (
    <NoteEditor
      // Remount key is the full note identity (vault + path) plus the edit
      // capability: keying on path alone would reuse a stale editor across a
      // cross-vault switch to the same path, and would also miss a change in
      // the user's access to this note (e.g. a live share revocation).
      key={`${vaultId}/${path}/${readOnly}`}
      vaultId={vaultId!}
      path={path!}
      vaultName={vault?.name}
      frontmatter={note.data!.frontmatter}
      initialBody={note.data!.body}
      readOnly={readOnly}
    />
  )
}

interface NoteEditorProps {
  vaultId: string
  path: string
  vaultName: string | undefined
  frontmatter: Record<string, unknown>
  initialBody: string
  readOnly: boolean
}

function NoteEditor({ vaultId, path, vaultName, frontmatter, initialBody, readOnly }: NoteEditorProps) {
  const updateNote = useUpdateNote(vaultId, path)
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)

  useEffect(() => {
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current)
    }
  }, [])

  function handleChange(newBody: string) {
    // Belt-and-suspenders: the editor is non-editable when readOnly, so this
    // shouldn't fire from user input — but never PUT an edit the server will
    // 404 anyway.
    if (readOnly) return
    if (timeoutRef.current) clearTimeout(timeoutRef.current)
    timeoutRef.current = setTimeout(() => {
      updateNote.mutate({ body: newBody })
    }, SAVE_DEBOUNCE_MS)
  }

  const tree = useVaultTree(vaultId)
  const wikilinkTargets = tree.data ? Object.values(tree.data).flat().map((n) => n.path) : []
  const editorRef = useCodeMirrorEditor({ doc: initialBody, onChange: handleChange, readOnly, wikilinkTargets })

  return (
    <div className="flex h-full flex-col">
      <div className="border-b border-border px-8 py-4 text-sm text-muted-foreground">
        {vaultName ?? vaultId} / <span className="text-foreground">{path}</span>
        {readOnly && <span className="ml-2 text-xs uppercase tracking-wide">· read-only</span>}
      </div>
      <div className="border-b border-border px-8 py-4">
        <PropertyPanel
          vaultId={vaultId}
          path={path}
          initialFrontmatter={frontmatter}
          readOnly={readOnly}
        />
      </div>
      <div ref={editorRef} className="flex-1 overflow-auto" />
    </div>
  )
}

import { useEffect, useRef } from 'react'
import { EditorState } from '@codemirror/state'
import { EditorView, keymap } from '@codemirror/view'
import { defaultKeymap, history, historyKeymap } from '@codemirror/commands'
import { markdown } from '@codemirror/lang-markdown'
import { HighlightStyle, syntaxHighlighting } from '@codemirror/language'
import { autocompletion } from '@codemirror/autocomplete'
import { tags } from '@lezer/highlight'
import { markdownMarkerHiding } from './markdownMarkerHiding.js'
import { wikilinkCompletions } from './wikilinkCompletions.js'

interface UseCodeMirrorEditorOptions {
  doc: string
  onChange: (doc: string) => void
  readOnly?: boolean
  wikilinkTargets?: string[]
}

const markdownHighlight = HighlightStyle.define([
  { tag: tags.heading1, class: 'cm-md-h1' },
  { tag: tags.heading2, class: 'cm-md-h2' },
  { tag: tags.heading3, class: 'cm-md-h3' },
  { tag: [tags.heading4, tags.heading5, tags.heading6], class: 'cm-md-h4' },
  { tag: tags.strong, class: 'cm-md-strong' },
  { tag: tags.emphasis, class: 'cm-md-emphasis' },
  { tag: tags.strikethrough, class: 'cm-md-strike' },
  { tag: tags.monospace, class: 'cm-md-code' },
  { tag: [tags.link, tags.url], class: 'cm-md-link' },
  { tag: tags.quote, class: 'cm-md-quote' },
])

export function useCodeMirrorEditor({
  doc,
  onChange,
  readOnly = false,
  wikilinkTargets = [],
}: UseCodeMirrorEditorOptions) {
  const containerRef = useRef<HTMLDivElement>(null)
  const onChangeRef = useRef(onChange)
  // Keep the ref pointing at the latest onChange without re-running the
  // mount effect below. Assigned in an effect (not during render) so the
  // update is a committed side effect — the CM6 updateListener only reads
  // this ref at edit time, always after this effect has run.
  useEffect(() => {
    onChangeRef.current = onChange
  })

  useEffect(() => {
    if (!containerRef.current) return

    const state = EditorState.create({
      doc,
      extensions: [
        history(),
        keymap.of([...defaultKeymap, ...historyKeymap]),
        markdown(),
        syntaxHighlighting(markdownHighlight),
        markdownMarkerHiding,
        autocompletion({ override: [wikilinkCompletions(wikilinkTargets)] }),
        EditorView.updateListener.of((update) => {
          if (update.docChanged) onChangeRef.current(update.state.doc.toString())
        }),
        EditorView.theme({
          '&': { fontFamily: 'var(--font-mono)', fontSize: '14px', height: '100%' },
          '.cm-content': { fontFamily: 'var(--font-mono)' },
          '.cm-scroller': { overflow: 'auto' },
          '.cm-md-h1': { fontSize: '1.6em', fontWeight: '700', lineHeight: '1.3' },
          '.cm-md-h2': { fontSize: '1.35em', fontWeight: '700', lineHeight: '1.3' },
          '.cm-md-h3': { fontSize: '1.15em', fontWeight: '700' },
          '.cm-md-h4': { fontWeight: '700' },
          '.cm-md-strong': { fontWeight: '700' },
          '.cm-md-emphasis': { fontStyle: 'italic' },
          '.cm-md-strike': { textDecoration: 'line-through' },
          '.cm-md-code': { fontFamily: 'var(--font-mono)', fontSize: '0.9em' },
          '.cm-md-link': { color: 'var(--primary)', textDecoration: 'underline' },
          '.cm-md-quote': { fontStyle: 'italic', color: 'var(--muted-foreground)' },
        }),
        // A genuinely non-editable rendered view needs BOTH: readOnly blocks
        // edit transactions/commands, editable=false drops contentEditable so
        // there's no caret. (CM6's documented recipe for a true read-only view.)
        ...(readOnly ? [EditorState.readOnly.of(true), EditorView.editable.of(false)] : []),
      ],
    })

    const view = new EditorView({ state, parent: containerRef.current })

    return () => {
      view.destroy()
    }
    // Mount once per component instance — `doc` and `readOnly` are captured at
    // mount. Callers that need a different `readOnly` remount this component
    // (Task 2 keys on it), matching how `doc` is already handled.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  return containerRef
}

import { describe, expect, it, vi } from 'vitest'
import { render } from '@testing-library/react'
import { useCodeMirrorEditor } from './useCodeMirrorEditor'

function Harness({
  doc,
  onChange,
  readOnly,
  wikilinkTargets,
}: {
  doc: string
  onChange: (doc: string) => void
  readOnly?: boolean
  wikilinkTargets?: string[]
}) {
  const ref = useCodeMirrorEditor({ doc, onChange, readOnly, wikilinkTargets })
  return <div ref={ref} data-testid="editor-container" />
}

describe('useCodeMirrorEditor', () => {
  it('mounts CodeMirror with the initial document text', () => {
    const { getByTestId } = render(<Harness doc="# Hello" onChange={vi.fn()} />)

    const container = getByTestId('editor-container')
    expect(container.querySelector('.cm-editor')).not.toBeNull()
    expect(container.querySelector('.cm-content')?.textContent).toBe('# Hello')
  })

  it('does not call onChange on mount', () => {
    const onChange = vi.fn()
    render(<Harness doc="# Hello" onChange={onChange} />)

    expect(onChange).not.toHaveBeenCalled()
  })

  it('is editable by default (contenteditable true)', () => {
    const { getByTestId } = render(<Harness doc="# Hello" onChange={vi.fn()} />)

    const content = getByTestId('editor-container').querySelector('.cm-content')
    expect(content?.getAttribute('contenteditable')).toBe('true')
  })

  it('is non-editable when readOnly is set (contenteditable false)', () => {
    const { getByTestId } = render(<Harness doc="# Hello" onChange={vi.fn()} readOnly />)

    const content = getByTestId('editor-container').querySelector('.cm-content')
    expect(content?.getAttribute('contenteditable')).toBe('false')
  })

  it('applies markdown styling classes (heading, strong, emphasis, code)', () => {
    const { getByTestId } = render(
      <Harness doc={'# Title\n\n**bold** and *italic* and `code`'} onChange={vi.fn()} />,
    )
    const container = getByTestId('editor-container')
    expect(container.querySelector('.cm-md-h1')).not.toBeNull()
    expect(container.querySelector('.cm-md-strong')).not.toBeNull()
    expect(container.querySelector('.cm-md-emphasis')).not.toBeNull()
    expect(container.querySelector('.cm-md-code')).not.toBeNull()
  })

  it('shows the heading marker when the cursor is on that line', () => {
    render(<Harness doc={'# Heading\n\nbody'} onChange={vi.fn()} />)
    // Default selection is at offset 0 → line 1 is active → marker visible.
    const firstLine = document.querySelector('.cm-line')
    expect(firstLine?.textContent).toBe('# Heading')
  })

  it('hides the heading marker when the cursor is on another line', async () => {
    render(<Harness doc={'# Heading\n\nbody'} onChange={vi.fn()} />)
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!
    // Move the cursor to the end (the "body" line) — line 1 is no longer active.
    view.dispatch({ selection: { anchor: view.state.doc.length } })
    const firstLine = document.querySelector('.cm-line')
    expect(firstLine?.textContent).toBe('Heading')
  })

  it('hides inline emphasis/code markers on an inactive line', async () => {
    render(<Harness doc={'top\n\n**bold** and `code`'} onChange={vi.fn()} />)
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!
    // Cursor on line 1 ("top"); the emphasis/code line is inactive.
    view.dispatch({ selection: { anchor: 0 } })
    const lines = document.querySelectorAll('.cm-line')
    const last = lines[lines.length - 1]
    expect(last?.textContent).toBe('bold and code')
  })

  it('reveals a hidden heading marker when the cursor moves back onto its line', async () => {
    render(<Harness doc={'# Heading\n\nbody'} onChange={vi.fn()} />)
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!

    // Off the heading line → hidden.
    view.dispatch({ selection: { anchor: view.state.doc.length } })
    expect(document.querySelector('.cm-line')?.textContent).toBe('Heading')

    // Back onto the heading line → revealed.
    view.dispatch({ selection: { anchor: 0 } })
    expect(document.querySelector('.cm-line')?.textContent).toBe('# Heading')
  })

  it('keeps fenced-code fences visible (does not blank the ``` lines)', async () => {
    render(<Harness doc={'intro\n\n```\ncode\n```'} onChange={vi.fn()} />)
    const { EditorView } = await import('@codemirror/view')
    const view = EditorView.findFromDOM(document.querySelector('.cm-editor') as HTMLElement)!
    // Cursor on line 1; the fenced block is inactive — fences must NOT be hidden.
    view.dispatch({ selection: { anchor: 0 } })
    const text = document.querySelector('.cm-content')?.textContent ?? ''
    expect(text).toContain('```')
    expect(text).toContain('code')
  })

  it('mounts with wikilinkTargets set (autocomplete wired, editor intact)', () => {
    const { getByTestId } = render(
      <Harness doc={'body'} onChange={vi.fn()} wikilinkTargets={['people/jane']} />,
    )
    const container = getByTestId('editor-container')
    expect(container.querySelector('.cm-content')?.textContent).toBe('body')
  })
})

